using System.Diagnostics;

namespace Av1rt.Aom;

internal static partial class entropymv
{
    // [port] default_nmv_context is generated by tools/gen/e1_tables.py as the C memory image of
    // the struct initializer; nmv_context_from_flat distributes it over the fields in C order.
    // <gen:tables>
    // nmv_context default_nmv_context (flat C memory image, see nmv_context_from_flat)
    private static readonly nmv_context default_nmv_context = nmv_context_from_flat(new aom_cdf_prob[] {
        28672, 21504, 13440, 0, 0, 4096, 1792, 910, 448, 217, 112, 28, 11, 6, 1, 0,
        0, 16384, 8192, 6144, 0, 0, 20480, 11520, 8640, 0, 0, 24576, 15360, 11520, 0, 0,
        16384, 0, 0, 12288, 0, 0, 16384, 0, 0, 5120, 0, 0, 15360, 0, 0, 14848,
        0, 0, 13824, 0, 0, 12288, 0, 0, 10240, 0, 0, 8192, 0, 0, 4096, 0,
        0, 2816, 0, 0, 2816, 0, 0, 2048, 0, 0, 4096, 1792, 910, 448, 217, 112,
        28, 11, 6, 1, 0, 0, 16384, 8192, 6144, 0, 0, 20480, 11520, 8640, 0, 0,
        24576, 15360, 11520, 0, 0, 16384, 0, 0, 12288, 0, 0, 16384, 0, 0, 5120, 0,
        0, 15360, 0, 0, 14848, 0, 0, 13824, 0, 0, 12288, 0, 0, 10240, 0, 0,
        8192, 0, 0, 4096, 0, 0, 2816, 0, 0, 2816, 0, 0, 2048, 0, 0
    });
    // </gen:tables>

    private static nmv_context nmv_context_from_flat(aom_cdf_prob[] flat)
    {
        var ctx = new nmv_context();
        int pos = 0;
        take(flat, ref pos, ctx.joints_cdf);
        for (int i = 0; i < ctx.comps.Length; i++)
        {
            nmv_component comp = ctx.comps[i];
            take(flat, ref pos, comp.classes_cdf);
            foreach (aom_cdf_prob[] cdf in comp.class0_fp_cdf) take(flat, ref pos, cdf);
            take(flat, ref pos, comp.fp_cdf);
            take(flat, ref pos, comp.sign_cdf);
            take(flat, ref pos, comp.class0_hp_cdf);
            take(flat, ref pos, comp.hp_cdf);
            take(flat, ref pos, comp.class0_cdf);
            foreach (aom_cdf_prob[] cdf in comp.bits_cdf) take(flat, ref pos, cdf);
        }
        Debug.Assert(pos == flat.Length);
        return ctx;

        static void take(aom_cdf_prob[] src, ref int p, aom_cdf_prob[] dst)
        {
            System.Array.Copy(src, p, dst, 0, dst.Length);
            p += dst.Length;
        }
    }

    internal static void av1_init_mv_probs(AV1_COMMON cm)
    {
        // NB: this sets CDFs too
        cm.fc.nmvc.CopyFrom(default_nmv_context);
        cm.fc.ndvc.CopyFrom(default_nmv_context);
    }
}
